<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $user = $args['user']; ?><form class="sd-form-grid" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="sd_update_profile"><?php wp_nonce_field( 'sd_profile_update' ); ?><div class="sd-field"><label for="sd-profile-name"><?php esc_html_e( 'Display name', 'social-discovery' ); ?></label><input id="sd-profile-name" name="display_name" value="<?php echo esc_attr( $user->display_name ); ?>" required></div><div class="sd-field"><label for="sd-profile-bio"><?php esc_html_e( 'Short biography', 'social-discovery' ); ?></label><textarea id="sd-profile-bio" name="description" rows="5"><?php echo esc_textarea( $user->description ); ?></textarea></div><div class="sd-field"><label for="sd-profile-url"><?php esc_html_e( 'Website', 'social-discovery' ); ?></label><input id="sd-profile-url" name="user_url" type="url" value="<?php echo esc_attr( $user->user_url ); ?>"></div><div class="sd-field"><label for="sd-profile-location"><?php esc_html_e( 'Location', 'social-discovery' ); ?></label><input id="sd-profile-location" name="location" value="<?php echo esc_attr( get_user_meta( $user->ID, 'sd_profile_location', true ) ); ?>"><p class="sd-field-help"><?php esc_html_e( 'Use a general location only; precise location is not required.', 'social-discovery' ); ?></p></div><button class="sd-button sd-button-primary" type="submit"><?php esc_html_e( 'Save profile', 'social-discovery' ); ?></button></form>
